#include <stdatomic.h>

typedef struct node { struct node *next; int val; } node_t;

/* ABA-safe reclamation: each thread publishes the pointers it is about to read */
#define HAZ_SLOTS 4
static _Thread_local void *hazards[HAZ_SLOTS];

static node_t *read_next(node_t *n) {
    for (;;) {
        void *p = atomic_load_explicit(&n->next, memory_order_acquire);
        hazards[0] = p;                                  /* publish BEFORE dereferencing */
        atomic_thread_fence(memory_order_seq_cst);       /* the seq_cst fence is what makes it safe */
        if (p == atomic_load_explicit(&n->next, memory_order_acquire)) {
            hazards[0] = NULL;
            return (node_t *)p;                          /* now safe to dereference */
        }
    }
}

/* reclamation: a node is freed only when no thread's hazard record names it */
static void scan_and_reclaim(void);
